from __future__ import annotations; from pathlib import Path; import yaml; from common.meta.extension import check_governance_exceptions as gec; ROOT = Path(__file__).resolve().parents[2]; REGISTRY = ROOT / 'common' / 'meta' / 'data' / 'governance-exceptions.yaml'
def test_AC8_13_131_registry_separates_proof_exceptions_and_code_owned_surfaces() -> None: 'AC8.13.131'; data = yaml.safe_load(REGISTRY.read_text(encoding='utf-8')); assert isinstance(data, dict); assert 'exceptions' in data; assert isinstance(data.get('proof_exceptions'), list); assert isinstance(data.get('code_owned_surfaces'), list); assert data['proof_exceptions'], 'at least one proof exception must be classified'; assert data['code_owned_surfaces'], 'at least one code-owned surface must be classified'
def test_AC8_13_131_every_classified_entry_links_an_owner_and_issue() -> None: 'AC-testing.governance.7 AC8.13.131'; violations = gec.validate_registry(REGISTRY); assert violations == [], '\n'.join(violations); 'AC8.13.131'; 'AC8.13.131'; assert gec.main([str(REGISTRY)]) == 0
def test_AC8_13_131_gate_rejects_unclassified_or_unsourced_entries(tmp_path: Path) -> None: 'AC8.13.131'; bad = tmp_path / 'governance-exceptions.yaml'; bad.write_text('version: 1\nexceptions: []\nproof_exceptions:\n  - id: missing-fields\ncode_owned_surfaces: []\n', encoding='utf-8'); violations = gec.validate_registry(bad); assert violations, 'registry with an unsourced proof exception must be rejected'
def test_AC_meta_governance_baseline_2_gate_rejects_stale_or_ambiguous_ssot_exceptions(tmp_path: Path) -> None: 'AC-meta.governance-baseline.2'; registry = tmp_path / 'governance-exceptions.yaml'; registry.write_text('version: 1\nexceptions:\n  - target: finance_report:debt:one\n    issue: https://github.com/wangzitian0/finance_report/issues/1869\n    reason: Needed while the base comparison is asymmetric.\n  - target: finance_report:debt:one\n    issue: https://github.com/wangzitian0/finance_report/issues/1869\n    reason: Duplicate target must fail.\nproof_exceptions: []\ncode_owned_surfaces: []\n', encoding='utf-8'); violations = gec.validate_registry(registry); assert any(("missing or empty 'remove_when'" in violation for violation in violations)); assert any(('duplicate temporary exception target' in violation for violation in violations))
